INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000029',1,'APPROVED','PUBLISHED',
'{"objectives":["Buy cinema tickets","Talk about film genres","Use welcher/welche/welches"],"explanation":{"intro":"Going to the cinema is a popular leisure activity. Learn to navigate ticket purchases and discuss films.","culturalNote":"Germany has a thriving film industry. The Berlin International Film Festival (Berlinale) is one of the top three film festivals in the world."},"examples":[{"german":"Zwei Karten für den Film, bitte.","english":"Two tickets for the film, please."},{"german":"Welcher Film läuft heute?","english":"Which film is showing today?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can buy cinema tickets and talk about films."}}',
'{"items":[{"word":"das Kino","translation":"cinema","pronunciation":"dahs KEE-noh","example":"Ich gehe ins Kino."},{"word":"die Karte","translation":"ticket","pronunciation":"dee KAR-teh","example":"Zwei Karten bitte."},{"word":"der Film","translation":"film","pronunciation":"dayr FILM","example":"Der Film ist gut."},{"word":"laufen","translation":"to screen/show","pronunciation":"LOW-fen","example":"Welcher Film läuft?"},{"word":"die Komödie","translation":"comedy","pronunciation":"dee koh-MÖ-dee-eh","example":"Ich mag Komödien."},{"word":"der Thriller","translation":"thriller","pronunciation":"dayr THRIL-er","example":"Der Thriller ist spannend."}]}',
'{"title":"Welcher/welche/welches — which","pattern":"welch- + gender ending matches noun gender","explanation":"Welcher (m), welche (f), welches (n) = which. It declines like der/die/das. Welcher Film = which film (der Film), welche Karte = which ticket (die Karte).","examples":[{"sentence":"Welcher Film läuft heute?","translation":"Which film is showing today?"},{"sentence":"Welche Karte möchten Sie?","translation":"Which ticket would you like?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Komödie'' means?","options":["comedy","thriller","action","drama"],"correctAnswer":"comedy"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Two tickets please.","options":["Zwei Karten bitte.","Ein Film bitte.","Welcher Film läuft?","Ich gehe ins Kino."],"correctAnswer":"Zwei Karten bitte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ Film läuft heute?","options":["Welcher","Welche","Welches","Was"],"correctAnswer":"Welcher"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The film is exciting","wordBankItems":["Der","Film","ist","spannend","."],"correctAnswer":"Der Film ist spannend ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Laufen'' in cinema context means?","options":["to screen/show","to run","to walk","to play"],"correctAnswer":"to screen/show"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-00000000002a',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about the beach","Name water activities","Use können for ability"],"explanation":{"intro":"Germany has beautiful coastline along the North Sea and Baltic Sea, as well as many inland lakes.","culturalNote":"The North Sea island of Sylt is Germany most exclusive beach resort. The Baltic coast (Ostsee) is popular for family holidays."},"examples":[{"german":"Ich kann schwimmen.","english":"I can swim."},{"german":"Der Strand ist wunderschön.","english":"The beach is beautiful."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about beach activities and say what I can do."}}',
'{"items":[{"word":"der Strand","translation":"beach","pronunciation":"dayr SHTRANT","example":"Wir gehen an den Strand."},{"word":"das Meer","translation":"sea","pronunciation":"dahs MAYR","example":"Das Meer ist blau."},{"word":"die Welle","translation":"wave","pronunciation":"dee VEL-leh","example":"Die Wellen sind groß."},{"word":"sonnenbaden","translation":"to sunbathe","pronunciation":"ZON-en-bah-den","example":"Ich bade in der Sonne."},{"word":"der Sonnenschirm","translation":"beach umbrella","pronunciation":"dayr ZON-en-shirm","example":"Ich brauche einen Sonnenschirm."},{"word":"die Sandburg","translation":"sandcastle","pronunciation":"dee ZANT-burg","example":"Wir bauen eine Sandburg."}]}',
'{"title":"Können — can/to be able to","pattern":"ich kann / du kannst / er kann + infinitive","explanation":"Können expresses ability. The infinitive goes to the end. Ich kann schwimmen = I can swim. Ich kann nicht tauchen = I cannot dive. It is a modal verb like müssen.","examples":[{"sentence":"Kannst du surfen?","translation":"Can you surf?"},{"sentence":"Ich kann gut schwimmen.","translation":"I can swim well."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Meer'' means?","options":["sea","beach","wave","lake"],"correctAnswer":"sea"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I can swim.","options":["Ich kann schwimmen.","Ich schwimme gern.","Das Meer ist groß.","Wir gehen an den Strand."],"correctAnswer":"Ich kann schwimmen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ du surfen?","options":["Kannst","Kannst","Kann","Könnest"],"correctAnswer":"Kannst"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We are building a sandcastle","wordBankItems":["Wir","bauen","eine","Sandburg","."],"correctAnswer":"Wir bauen eine Sandburg ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Sonnenbaden'' means?","options":["to sunbathe","to swim","to surf","to dive"],"correctAnswer":"to sunbathe"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-00000000002b',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about mountain activities","Use wollen for intentions","Describe landscapes"],"explanation":{"intro":"The German Alps (Bayerische Alpen) attract millions of visitors. Hiking and skiing are popular year-round.","culturalNote":"The Zugspitze at 2962m is Germany highest mountain, on the border with Austria. It has a famous summit restaurant."},"examples":[{"german":"Ich will auf den Gipfel.","english":"I want to go to the summit."},{"german":"Die Aussicht ist fantastisch.","english":"The view is fantastic."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about mountain activities and landscapes."}}',
'{"items":[{"word":"der Gipfel","translation":"summit/peak","pronunciation":"dayr GIP-fel","example":"Wir sind auf dem Gipfel."},{"word":"die Aussicht","translation":"view","pronunciation":"dee OWS-zikht","example":"Die Aussicht ist toll."},{"word":"der Wanderweg","translation":"hiking trail","pronunciation":"dayr VAN-der-veg","example":"Der Wanderweg ist steil."},{"word":"die Seilbahn","translation":"cable car","pronunciation":"dee ZYL-bahn","example":"Wir nehmen die Seilbahn."},{"word":"steil","translation":"steep","pronunciation":"SHTYL","example":"Der Weg ist steil."},{"word":"die Hütte","translation":"mountain hut","pronunciation":"dee HÜT-teh","example":"Wir übernachten in der Hütte."}]}',
'{"title":"Wollen — to want to","pattern":"ich will / du willst / er will + infinitive","explanation":"Wollen expresses a strong intention or desire. Ich will wandern = I want to hike. Like all modals, the infinitive goes to the end. Ich will auf den Gipfel = I want to go to the summit.","examples":[{"sentence":"Ich will die Seilbahn nehmen.","translation":"I want to take the cable car."},{"sentence":"Willst du wandern?","translation":"Do you want to hike?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Gipfel'' means?","options":["summit","trail","hut","view"],"correctAnswer":"summit"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The view is fantastic.","options":["Die Aussicht ist fantastisch.","Der Weg ist steil.","Wir nehmen die Seilbahn.","Ich will wandern."],"correctAnswer":"Die Aussicht ist fantastisch."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ auf den Gipfel.","options":["will","kann","muss","mag"],"correctAnswer":"will"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The hiking trail is steep","wordBankItems":["Der","Wanderweg","ist","steil","."],"correctAnswer":"Der Wanderweg ist steil ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Hütte'' means?","options":["mountain hut","hotel","tent","cable car"],"correctAnswer":"mountain hut"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-00000000002c',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a typical German breakfast","Order breakfast items","Use zum Frühstück"],"explanation":{"intro":"A German breakfast (Frühstück) is hearty and varied — bread, cold cuts, cheese, eggs, and coffee are typical.","culturalNote":"Germans take breakfast seriously. A typical Frühstücksbuffet at a hotel or café offers Brötchen, Aufschnitt, Käse, Marmelade, and hot drinks."},"examples":[{"german":"Zum Frühstück esse ich Brot mit Marmelade.","english":"For breakfast I eat bread with jam."},{"german":"Was möchten Sie zum Frühstück?","english":"What would you like for breakfast?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can describe and order a German breakfast."}}',
'{"items":[{"word":"das Frühstück","translation":"breakfast","pronunciation":"dahs FRÜH-shtük","example":"Ich esse Frühstück."},{"word":"das Ei","translation":"egg","pronunciation":"dahs EY","example":"Ich mag gekochte Eier."},{"word":"die Marmelade","translation":"jam","pronunciation":"dee mar-meh-LAH-deh","example":"Brot mit Marmelade."},{"word":"der Aufschnitt","translation":"cold cuts","pronunciation":"dayr OWF-shnit","example":"Aufschnitt zum Frühstück."},{"word":"der Orangensaft","translation":"orange juice","pronunciation":"dayr oh-RAN-zhen-zaft","example":"Ein Glas Orangensaft."},{"word":"zum","translation":"for (meal)","pronunciation":"TSOOM","example":"Was gibt es zum Frühstück?"}]}',
'{"title":"Zum + meal time","pattern":"zum Frühstück / zum Mittagessen / zum Abendessen","explanation":"Use zum (= zu + dem, dative) to say what you eat at a specific meal. Zum Frühstück esse ich Müsli = For breakfast I eat muesli. Zum is a fixed dative contraction.","examples":[{"sentence":"Zum Frühstück trinke ich Kaffee.","translation":"For breakfast I drink coffee."},{"sentence":"Was gibt es zum Abendessen?","translation":"What is there for dinner?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Marmelade'' means?","options":["jam","butter","cheese","egg"],"correctAnswer":"jam"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"For breakfast I eat bread.","options":["Zum Frühstück esse ich Brot.","Ich mag Eier.","Was gibt es?","Der Aufschnitt ist gut."],"correctAnswer":"Zum Frühstück esse ich Brot."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich trinke ___ Frühstück Kaffee.","options":["zum","zur","beim","im"],"correctAnswer":"zum"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: A glass of orange juice","wordBankItems":["Ein","Glas","Orangensaft","."],"correctAnswer":"Ein Glas Orangensaft ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Aufschnitt'' means?","options":["cold cuts","cheese","bread","butter"],"correctAnswer":"cold cuts"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-00000000002d',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about lunch","Order a midday meal","Use nehmen for ordering"],"explanation":{"intro":"Mittagessen is the main meal in Germany, traditionally eaten around noon. Many workers go to a Kantine (canteen) or nearby restaurant.","culturalNote":"Das Tagesgericht (dish of the day) is posted outside most German restaurants and offers a cheaper midday option."},"examples":[{"german":"Was ist das Tagesgericht?","english":"What is the dish of the day?"},{"german":"Ich nehme die Suppe.","english":"I will have the soup."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can order a midday meal and ask about daily specials."}}',
'{"items":[{"word":"das Mittagessen","translation":"lunch","pronunciation":"dahs MIT-tahk-es-en","example":"Ich esse Mittagessen."},{"word":"das Tagesgericht","translation":"dish of the day","pronunciation":"dahs TAH-ges-geh-rikht","example":"Das Tagesgericht kostet 8 Euro."},{"word":"die Suppe","translation":"soup","pronunciation":"dee ZUP-peh","example":"Die Suppe ist heiß."},{"word":"der Salat","translation":"salad","pronunciation":"dayr zah-LAHT","example":"Ich nehme den Salat."},{"word":"die Kantine","translation":"canteen","pronunciation":"dee kan-TEE-neh","example":"Wir essen in der Kantine."},{"word":"nehmen","translation":"to have/take (ordering)","pronunciation":"NAY-men","example":"Ich nehme das Schnitzel."}]}',
'{"title":"Nehmen for ordering","pattern":"ich nehme + dish (accusative)","explanation":"In restaurants, nehmen (to take) is used to say what you are ordering. Ich nehme die Suppe = I will have the soup. It is more decisive than ich möchte and very natural in restaurant settings.","examples":[{"sentence":"Ich nehme das Tagesgericht.","translation":"I will have the dish of the day."},{"sentence":"Was nimmst du?","translation":"What are you having?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Tagesgericht'' means?","options":["dish of the day","lunch","canteen","soup"],"correctAnswer":"dish of the day"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I will have the salad.","options":["Ich nehme den Salat.","Ich nehme die Suppe.","Was ist das Tagesgericht?","Wir essen in der Kantine."],"correctAnswer":"Ich nehme den Salat."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Was ___ du?","options":["nimmst","nehme","nimmt","nehmt"],"correctAnswer":"nimmst"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The soup is hot","wordBankItems":["Die","Suppe","ist","heiß","."],"correctAnswer":"Die Suppe ist heiß ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Kantine'' means?","options":["canteen","restaurant","café","kitchen"],"correctAnswer":"canteen"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-00000000002e',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a typical dinner","Use abends for evening time","Talk about cooking at home"],"explanation":{"intro":"Abendessen in Germany is traditionally a lighter meal — often bread, cold cuts and cheese. Many Germans cook a warm meal in the evening too.","culturalNote":"Abendbrot (evening bread) is the traditional German supper — cold food on bread. It reflects the culture of having the hot meal at midday."},"examples":[{"german":"Abends essen wir meistens Abendbrot.","english":"In the evenings we usually eat Abendbrot."},{"german":"Ich koche heute Abend Pasta.","english":"I am cooking pasta this evening."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about dinner and describe what I cook."}}',
'{"items":[{"word":"das Abendessen","translation":"dinner","pronunciation":"dahs AH-bent-es-en","example":"Wann ist Abendessen?"},{"word":"das Abendbrot","translation":"evening bread (traditional supper)","pronunciation":"dahs AH-bent-broht","example":"Wir essen Abendbrot."},{"word":"meistens","translation":"usually/mostly","pronunciation":"MYS-tens","example":"Ich esse meistens zu Hause."},{"word":"kochen","translation":"to cook","pronunciation":"KOKH-en","example":"Er kocht Abendessen."},{"word":"die Pasta","translation":"pasta","pronunciation":"dee PAS-tah","example":"Ich koche Pasta."},{"word":"zu Hause","translation":"at home","pronunciation":"tsoo HOW-zeh","example":"Ich esse zu Hause."}]}',
'{"title":"Meistens / oft / manchmal — frequency adverbs","pattern":"frequency adverb + verb or verb + frequency adverb","explanation":"Frequency adverbs: immer (always), meistens (mostly/usually), oft (often), manchmal (sometimes), selten (rarely), nie (never). They typically come after the verb in main clauses: Ich esse meistens zu Hause.","examples":[{"sentence":"Ich koche oft Abendessen.","translation":"I often cook dinner."},{"sentence":"Wir essen manchmal auswärts.","translation":"We sometimes eat out."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Meistens'' means?","options":["usually","sometimes","never","always"],"correctAnswer":"usually"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am cooking pasta this evening.","options":["Ich koche heute Abend Pasta.","Wir essen Abendbrot.","Ich esse zu Hause.","Das Abendessen ist fertig."],"correctAnswer":"Ich koche heute Abend Pasta."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich esse ___ zu Hause.","options":["meistens","vielleicht","bestimmt","sofort"],"correctAnswer":"meistens"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We eat at home","wordBankItems":["Wir","essen","zu","Hause","."],"correctAnswer":"Wir essen zu Hause ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Abendbrot'' means?","options":["evening bread supper","breakfast","lunch","snack"],"correctAnswer":"evening bread supper"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-00000000002f',1,'APPROVED','PUBLISHED',
'{"objectives":["Name fruits and vegetables","Use fresh produce vocabulary","Talk about dietary preferences"],"explanation":{"intro":"Germany has rich farmers market culture. Knowing fruit and vegetable names helps with shopping, cooking and healthy eating conversations.","culturalNote":"Germans love their Kartoffeln (potatoes). Germany produces over 10 million tonnes of potatoes per year and they appear in hundreds of traditional recipes."},"examples":[{"german":"Ich mag Erdbeeren am liebsten.","english":"I like strawberries the most."},{"german":"Kartoffeln sind sehr beliebt in Deutschland.","english":"Potatoes are very popular in Germany."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name common fruits and vegetables."}}',
'{"items":[{"word":"die Erdbeere","translation":"strawberry","pronunciation":"dee AYRT-bay-reh","example":"Ich esse Erdbeeren."},{"word":"die Kartoffel","translation":"potato","pronunciation":"dee kar-TOF-fel","example":"Kartoffeln sind lecker."},{"word":"die Karotte","translation":"carrot","pronunciation":"dee kah-ROT-teh","example":"Karotten sind gesund."},{"word":"der Apfel","translation":"apple","pronunciation":"dayr AP-fel","example":"Ein Apfel täglich."},{"word":"die Banane","translation":"banana","pronunciation":"dee bah-NAH-neh","example":"Ich esse eine Banane."},{"word":"der Spinat","translation":"spinach","pronunciation":"dayr shpee-NAHT","example":"Spinat ist sehr gesund."}]}',
'{"title":"Am liebsten — liking most","pattern":"ich mag + noun + am liebsten","explanation":"Am liebsten means the most / favourite. Ich mag Äpfel am liebsten = I like apples the most / apples are my favourite. It comes at the end of the sentence and never changes form.","examples":[{"sentence":"Ich esse Erdbeeren am liebsten.","translation":"Strawberries are my favourite to eat."},{"sentence":"Er mag Kartoffeln am liebsten.","translation":"Potatoes are his favourite."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Karotte'' means?","options":["carrot","potato","apple","banana"],"correctAnswer":"carrot"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Strawberries are my favourite.","options":["Ich mag Erdbeeren am liebsten.","Kartoffeln sind lecker.","Ich esse Spinat.","Karotten sind gesund."],"correctAnswer":"Ich mag Erdbeeren am liebsten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Spinat ist sehr ___.","options":["gesund","lecker","frisch","teuer"],"correctAnswer":"gesund"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: An apple a day","wordBankItems":["Ein","Apfel","täglich","."],"correctAnswer":"Ein Apfel täglich ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Am liebsten'' means?","options":["the most/favourite","also","always","very"],"correctAnswer":"the most/favourite"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000030',1,'APPROVED','PUBLISHED',
'{"objectives":["Name German beverages","Order drinks at a bar","Use ein Glas and eine Flasche"],"explanation":{"intro":"Germany is famous for its beer culture but also has excellent wine, coffee, and mineral water traditions.","culturalNote":"Germany has over 1,300 breweries. The Reinheitsgebot (beer purity law) from 1516 stipulates that beer may only contain water, barley and hops."},"examples":[{"german":"Ein Bier, bitte.","english":"A beer, please."},{"german":"Ich trinke lieber Wein.","english":"I prefer drinking wine."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can order drinks and name German beverages."}}',
'{"items":[{"word":"das Bier","translation":"beer","pronunciation":"dahs BEER","example":"Ein Bier, bitte."},{"word":"der Wein","translation":"wine","pronunciation":"dayr VYN","example":"Ein Glas Wein."},{"word":"das Mineralwasser","translation":"mineral water","pronunciation":"dahs mee-neh-RAHL-vas-ser","example":"Stilles oder sprudelndes Wasser?"},{"word":"der Apfelsaft","translation":"apple juice","pronunciation":"dayr AP-fel-zaft","example":"Ein Apfelsaft bitte."},{"word":"sprudelnd","translation":"sparkling","pronunciation":"SHROO-delnt","example":"Sprudelnd oder still?"},{"word":"lieber","translation":"preferably/rather","pronunciation":"LEE-ber","example":"Ich trinke lieber Tee."}]}',
'{"title":"Lieber — preference (rather)","pattern":"ich + verb + lieber + item","explanation":"Lieber means rather or prefer. Ich trinke lieber Wasser = I prefer drinking water / I would rather drink water. Ich esse lieber Fisch als Fleisch = I prefer fish to meat. Very common in food and drink contexts.","examples":[{"sentence":"Ich trinke lieber Wein.","translation":"I prefer wine."},{"sentence":"Magst du lieber Kaffee oder Tee?","translation":"Do you prefer coffee or tea?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Sprudelnd'' means?","options":["sparkling","still","cold","warm"],"correctAnswer":"sparkling"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I prefer drinking tea.","options":["Ich trinke lieber Tee.","Ein Bier bitte.","Ich mag Wein.","Stilles Wasser bitte."],"correctAnswer":"Ich trinke lieber Tee."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ein Glas ___ bitte.","options":["Wein","Weins","Weine","Weinen"],"correctAnswer":"Wein"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Sparkling or still?","wordBankItems":["Sprudelnd","oder","still","?"],"correctAnswer":"Sprudelnd oder still ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Lieber'' means?","options":["rather/prefer","also","very","more"],"correctAnswer":"rather/prefer"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000031',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a morning routine","Use reflexive verbs","Say what time you do things"],"explanation":{"intro":"Morning routine vocabulary uses reflexive verbs — verbs where the subject acts on themselves. These are very common in daily life German.","culturalNote":"Germans tend to be punctual — being on time is very important in professional and social life. Starting the day efficiently matters."},"examples":[{"german":"Ich stehe um 7 Uhr auf.","english":"I get up at 7 oclock."},{"german":"Ich dusche mich jeden Morgen.","english":"I shower every morning."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can describe my morning routine using reflexive verbs."}}',
'{"items":[{"word":"aufstehen","translation":"to get up","pronunciation":"OWF-shtay-en","example":"Ich stehe um 7 auf."},{"word":"sich duschen","translation":"to shower","pronunciation":"zikh DOO-shen","example":"Ich dusche mich."},{"word":"sich anziehen","translation":"to get dressed","pronunciation":"zikh AN-tsee-en","example":"Ich ziehe mich an."},{"word":"sich die Zähne putzen","translation":"to brush teeth","pronunciation":"zikh dee TSAY-neh PUT-sen","example":"Ich putze mir die Zähne."},{"word":"frühstücken","translation":"to have breakfast","pronunciation":"FRÜH-shtük-en","example":"Ich frühstücke um 8."},{"word":"der Wecker","translation":"alarm clock","pronunciation":"dayr VEK-er","example":"Mein Wecker klingelt."}]}',
'{"title":"Reflexive verbs: sich + verb","pattern":"ich + verb + mich / du + verb + dich / er + verb + sich","explanation":"Reflexive verbs use a reflexive pronoun: mich (me), dich (you), sich (him/her/itself). Ich dusche mich = I shower myself. Many daily routine verbs are reflexive in German.","examples":[{"sentence":"Ich ziehe mich an.","translation":"I get dressed."},{"sentence":"Er rasiert sich.","translation":"He shaves."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Aufstehen'' means?","options":["to get up","to shower","to eat","to sleep"],"correctAnswer":"to get up"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I shower every morning.","options":["Ich dusche mich jeden Morgen.","Ich stehe früh auf.","Mein Wecker klingelt.","Ich frühstücke um 8."],"correctAnswer":"Ich dusche mich jeden Morgen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ziehe ___ an.","options":["mich","mir","sich","dich"],"correctAnswer":"mich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My alarm clock rings","wordBankItems":["Mein","Wecker","klingelt","."],"correctAnswer":"Mein Wecker klingelt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Wecker'' means?","options":["alarm clock","watch","morning","time"],"correctAnswer":"alarm clock"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000032',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe an evening routine","Use sich entspannen","Talk about bedtime"],"explanation":{"intro":"Evening routines in German use the same reflexive verbs as morning routines. Learn to describe how you wind down.","culturalNote":"Germans value Feierabend — the end of the working day and the beginning of personal time. Prost auf den Feierabend! (Cheers to the end of the working day!)"},"examples":[{"german":"Abends entspanne ich mich.","english":"In the evenings I relax."},{"german":"Ich gehe um 23 Uhr ins Bett.","english":"I go to bed at 11pm."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can describe my evening routine."}}',
'{"items":[{"word":"sich entspannen","translation":"to relax","pronunciation":"zikh ent-SHPAN-en","example":"Ich entspanne mich."},{"word":"fernsehen","translation":"to watch TV","pronunciation":"FERN-zay-en","example":"Ich sehe fern."},{"word":"ins Bett gehen","translation":"to go to bed","pronunciation":"ins BET GAY-en","example":"Ich gehe ins Bett."},{"word":"schlafen","translation":"to sleep","pronunciation":"SHLAH-fen","example":"Ich schlafe gut."},{"word":"lesen","translation":"to read","pronunciation":"LAY-zen","example":"Ich lese vor dem Schlafen."},{"word":"der Feierabend","translation":"end of working day","pronunciation":"dayr FY-er-ah-bent","example":"Endlich Feierabend!"}]}',
'{"title":"Separable verb: fernsehen","pattern":"ich sehe fern (prefix splits off)","explanation":"Fernsehen (to watch TV) is separable: sehen is the base verb, fern is the prefix. Ich sehe fern (not Ich fernsehe). Same pattern: aufstehen → ich stehe auf, anziehen → ich ziehe an.","examples":[{"sentence":"Ich sehe jeden Abend fern.","translation":"I watch TV every evening."},{"sentence":"Siehst du gern fern?","translation":"Do you like watching TV?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Sich entspannen'' means?","options":["to relax","to sleep","to read","to watch TV"],"correctAnswer":"to relax"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I go to bed at 10pm.","options":["Ich gehe um 22 Uhr ins Bett.","Ich schlafe gut.","Ich entspanne mich.","Endlich Feierabend!"],"correctAnswer":"Ich gehe um 22 Uhr ins Bett."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich sehe jeden Abend ___.","options":["fern","auf","an","ab"],"correctAnswer":"fern"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I read before sleeping","wordBankItems":["Ich","lese","vor","dem","Schlafen","."],"correctAnswer":"Ich lese vor dem Schlafen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Feierabend'' means?","options":["end of working day","holiday","evening","weekend"],"correctAnswer":"end of working day"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000033',1,'APPROVED','PUBLISHED',
'{"objectives":["Make plans for the weekend","Suggest activities","Use Lust haben for desire"],"explanation":{"intro":"Weekend vocabulary lets you make plans, suggest activities and talk about leisure time.","culturalNote":"Sundays in Germany are quiet — most shops are closed and loud activities like DIY are restricted. It is a day for rest and family."},"examples":[{"german":"Hast du Lust, ins Kino zu gehen?","english":"Do you feel like going to the cinema?"},{"german":"Am Wochenende mache ich nichts.","english":"I am doing nothing at the weekend."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can make and discuss plans for the weekend."}}',
'{"items":[{"word":"das Wochenende","translation":"weekend","pronunciation":"dahs VOH-khen-en-deh","example":"Am Wochenende bin ich frei."},{"word":"Lust haben","translation":"to feel like / to fancy","pronunciation":"LOOST HAH-ben","example":"Hast du Lust?"},{"word":"der Plan","translation":"plan","pronunciation":"dayr PLAHN","example":"Was ist der Plan?"},{"word":"ausgehen","translation":"to go out","pronunciation":"OWS-gay-en","example":"Wir gehen aus."},{"word":"relaxen","translation":"to relax/chill","pronunciation":"reh-LAK-sen","example":"Ich relaxe am Wochenende."},{"word":"nichts","translation":"nothing","pronunciation":"NIKHTS","example":"Ich mache nichts."}]}',
'{"title":"Lust haben + zu + infinitive","pattern":"Hast du Lust + zu + infinitive?","explanation":"Lust haben + zu + infinitive means to feel like doing something. Hast du Lust, schwimmen zu gehen? = Do you feel like going swimming? The infinitive with zu goes at the end. Very common for making suggestions.","examples":[{"sentence":"Hast du Lust, spazieren zu gehen?","translation":"Do you feel like going for a walk?"},{"sentence":"Ich habe keine Lust.","translation":"I do not feel like it."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Lust haben'' means?","options":["to feel like","to want","to must","to be able to"],"correctAnswer":"to feel like"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Do you feel like going out?","options":["Hast du Lust auszugehen?","Was machst du am Wochenende?","Ich relaxe zu Hause.","Am Wochenende bin ich frei."],"correctAnswer":"Hast du Lust auszugehen?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich mache ___ am Wochenende.","options":["nichts","alles","viel","wenig"],"correctAnswer":"nichts"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We are going out","wordBankItems":["Wir","gehen","aus","."],"correctAnswer":"Wir gehen aus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ausgehen'' means?","options":["to go out","to go home","to arrive","to depart"],"correctAnswer":"to go out"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000034',1,'APPROVED','PUBLISHED',
'{"objectives":["Name German public holidays","Describe holiday traditions","Use an + holidays"],"explanation":{"intro":"Germany has several national public holidays plus additional state-specific holidays. Knowing them helps you plan around closures and join in cultural conversations.","culturalNote":"Germany has more public holidays than most European countries. Tag der Deutschen Einheit (German Unity Day) on October 3rd celebrates reunification in 1990."},"examples":[{"german":"Am ersten Mai ist Tag der Arbeit.","english":"On the first of May is Labour Day."},{"german":"An Ostern fahren wir zu meiner Familie.","english":"At Easter we go to my family."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name German public holidays and describe traditions."}}',
'{"items":[{"word":"der Feiertag","translation":"public holiday","pronunciation":"dayr FY-er-tahk","example":"Morgen ist ein Feiertag."},{"word":"Weihnachten","translation":"Christmas","pronunciation":"VY-nakh-ten","example":"Frohe Weihnachten!"},{"word":"Ostern","translation":"Easter","pronunciation":"OH-stern","example":"Frohe Ostern!"},{"word":"Pfingsten","translation":"Whitsun/Pentecost","pronunciation":"PFING-sten","example":"An Pfingsten bin ich frei."},{"word":"der Heilige Abend","translation":"Christmas Eve","pronunciation":"dayr HY-lih-geh AH-bent","example":"Am Heiligen Abend."},{"word":"frei haben","translation":"to have a day off","pronunciation":"FRY HAH-ben","example":"Morgen habe ich frei."}]}',
'{"title":"An + holiday (dative)","pattern":"an + dem (dem/der) + holiday = at/on a holiday","explanation":"Use an + dative for holidays and specific days. An Weihnachten = at Christmas. An Ostern = at Easter. For weekdays: am Montag. For holidays that are plural or neuter: an Weihnachten (n.), an Ostern (n.).","examples":[{"sentence":"An Weihnachten sind alle Geschäfte zu.","translation":"At Christmas all shops are closed."},{"sentence":"Was machst du an Ostern?","translation":"What are you doing at Easter?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Feiertag'' means?","options":["public holiday","birthday","festival","weekend"],"correctAnswer":"public holiday"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Merry Christmas!","options":["Frohe Weihnachten!","Frohe Ostern!","Prost!","Herzlichen Glückwunsch!"],"correctAnswer":"Frohe Weihnachten!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ Ostern fahren wir weg.","options":["An","Am","Im","Zu"],"correctAnswer":"An"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Tomorrow I have a day off","wordBankItems":["Morgen","habe","ich","frei","."],"correctAnswer":"Morgen habe ich frei ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Heilige Abend'' means?","options":["Christmas Eve","Christmas Day","New Year","Easter"],"correctAnswer":"Christmas Eve"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000035',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about Christmas traditions","Describe Advent and decorations","Use the genitive for possessives"],"explanation":{"intro":"Christmas is the biggest holiday in Germany. The traditions include Adventskranz, Weihnachtsmarkt, Stollen and the exchange of gifts.","culturalNote":"German Christmas markets (Weihnachtsmärkte) are world-famous. The market in Nuremberg (Christkindlesmarkt) has been running since the 16th century."},"examples":[{"german":"Der Weihnachtsmarkt ist wunderschön.","english":"The Christmas market is beautiful."},{"german":"Wir schmücken den Weihnachtsbaum.","english":"We decorate the Christmas tree."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about Christmas traditions in Germany."}}',
'{"items":[{"word":"der Weihnachtsbaum","translation":"Christmas tree","pronunciation":"dayr VY-nakhts-bowm","example":"Wir kaufen einen Weihnachtsbaum."},{"word":"der Weihnachtsmarkt","translation":"Christmas market","pronunciation":"dayr VY-nakhts-markt","example":"Der Weihnachtsmarkt ist schön."},{"word":"der Advent","translation":"Advent","pronunciation":"dayr ad-VENT","example":"Der Advent beginnt im Dezember."},{"word":"der Stollen","translation":"Stollen (Christmas cake)","pronunciation":"dayr SHTOL-en","example":"Ich esse gern Stollen."},{"word":"schmücken","translation":"to decorate","pronunciation":"SHMÜK-en","example":"Wir schmücken den Baum."},{"word":"das Geschenk","translation":"present/gift","pronunciation":"dahs geh-SHENK","example":"Ich öffne mein Geschenk."}]}',
'{"title":"Wir schmücken — decorating vocabulary","pattern":"schmücken + accusative object","explanation":"Schmücken means to decorate. Den Weihnachtsbaum schmücken = to decorate the Christmas tree. Den is accusative masculine. Common Christmas verbs: schmücken (decorate), backen (bake), verschenken (give as a gift), feiern (celebrate).","examples":[{"sentence":"Wir backen Plätzchen.","translation":"We bake cookies."},{"sentence":"Ich verschenke Bücher.","translation":"I give books as gifts."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Weihnachtsmarkt'' means?","options":["Christmas market","Christmas tree","Advent","present"],"correctAnswer":"Christmas market"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"We decorate the Christmas tree.","options":["Wir schmücken den Weihnachtsbaum.","Ich öffne mein Geschenk.","Der Markt ist schön.","Ich esse Stollen."],"correctAnswer":"Wir schmücken den Weihnachtsbaum."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich öffne mein ___.","options":["Geschenk","Baum","Markt","Licht"],"correctAnswer":"Geschenk"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The Christmas market is beautiful","wordBankItems":["Der","Weihnachtsmarkt","ist","wunderschön","."],"correctAnswer":"Der Weihnachtsmarkt ist wunderschön ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Schmücken'' means?","options":["to decorate","to bake","to celebrate","to give"],"correctAnswer":"to decorate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000036',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about Easter traditions","Use Ostern vocabulary","Describe spring activities"],"explanation":{"intro":"Ostern is celebrated with egg hunts, family gatherings, and spring lamb dishes. Both Good Friday and Easter Monday are public holidays.","culturalNote":"Germans decorate eggs and trees for Easter. The Osterbrunnen (Easter fountain) tradition in Franconia sees village fountains decorated with painted eggs."},"examples":[{"german":"Wir suchen Ostereier im Garten.","english":"We look for Easter eggs in the garden."},{"german":"Frohe Ostern!","english":"Happy Easter!"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about Easter and German spring traditions."}}',
'{"items":[{"word":"das Osterei","translation":"Easter egg","pronunciation":"dahs OH-ster-eye","example":"Wir bemalen Ostereier."},{"word":"der Osterhase","translation":"Easter bunny","pronunciation":"dayr OH-ster-hah-zeh","example":"Der Osterhase bringt Geschenke."},{"word":"bemalen","translation":"to paint/decorate","pronunciation":"beh-MAH-len","example":"Wir bemalen Eier."},{"word":"suchen","translation":"to search for","pronunciation":"ZOO-khen","example":"Wir suchen Eier."},{"word":"der Frühling","translation":"spring","pronunciation":"dayr FRÜH-ling","example":"Im Frühling feiern wir Ostern."},{"word":"verstecken","translation":"to hide","pronunciation":"fer-SHTEK-en","example":"Ich verstecke die Eier."}]}',
'{"title":"Wir suchen / wir verstecken — Easter verbs","pattern":"action verbs for games and search activities","explanation":"Suchen (to search) and verstecken (to hide) are the core Easter hunt verbs. Wir verstecken die Eier = We hide the eggs. Die Kinder suchen die Eier = The children search for the eggs. Both take accusative objects.","examples":[{"sentence":"Die Kinder suchen die Ostereier.","translation":"The children search for the Easter eggs."},{"sentence":"Der Vater versteckt die Geschenke.","translation":"The father hides the presents."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Osterhase'' means?","options":["Easter bunny","Easter egg","spring","Easter"],"correctAnswer":"Easter bunny"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"We paint Easter eggs.","options":["Wir bemalen Ostereier.","Wir suchen Eier.","Frohe Ostern!","Der Frühling ist schön."],"correctAnswer":"Wir bemalen Ostereier."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ die Eier im Garten.","options":["verstecke","suche","male","finde"],"correctAnswer":"verstecke"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Happy Easter!","wordBankItems":["Frohe","Ostern","!"],"correctAnswer":"Frohe Ostern !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bemalen'' means?","options":["to paint/decorate","to search","to hide","to find"],"correctAnswer":"to paint/decorate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000037',1,'APPROVED','PUBLISHED',
'{"objectives":["Introduce yourself at work","Use formal Sie","Exchange professional information"],"explanation":{"intro":"First day at a German workplace requires formal introductions. Using Sie (formal you) is essential until invited to switch to du.","culturalNote":"In Germany it is normal to use last names and Sie with colleagues until they invite you to use first names (das Du anbieten). This transition can take months."},"examples":[{"german":"Darf ich mich vorstellen? Ich bin Herr Müller.","english":"May I introduce myself? I am Mr Müller."},{"german":"Was machen Sie beruflich?","english":"What do you do professionally?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can introduce myself formally in a work context."}}',
'{"items":[{"word":"sich vorstellen","translation":"to introduce oneself","pronunciation":"zikh FOR-shtel-en","example":"Darf ich mich vorstellen?"},{"word":"beruflich","translation":"professionally","pronunciation":"beh-ROOF-likh","example":"Was machen Sie beruflich?"},{"word":"die Abteilung","translation":"department","pronunciation":"dee ap-TY-loong","example":"Ich bin in der Marketingabteilung."},{"word":"der Kollege","translation":"colleague (m)","pronunciation":"dayr kol-LAY-geh","example":"Das ist mein Kollege."},{"word":"zuständig für","translation":"responsible for","pronunciation":"TSOO-shtend-ikh für","example":"Ich bin zuständig für IT."},{"word":"angenehm","translation":"pleased to meet you","pronunciation":"AN-geh-naym","example":"Angenehm, Sie kennenzulernen."}]}',
'{"title":"Darf ich — may I (polite permission)","pattern":"Darf ich + infinitive?","explanation":"Darf ich is the polite way to ask permission. Darf ich mich vorstellen? = May I introduce myself? Darf ich fragen? = May I ask? Dürfen is a modal verb: ich darf, du darfst, er darf.","examples":[{"sentence":"Darf ich Ihnen helfen?","translation":"May I help you?"},{"sentence":"Darf ich fragen, wo Sie arbeiten?","translation":"May I ask where you work?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Abteilung'' means?","options":["department","company","office","colleague"],"correctAnswer":"department"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"May I introduce myself?","options":["Darf ich mich vorstellen?","Was machen Sie beruflich?","Angenehm Sie kennenzulernen.","Ich bin zuständig für IT."],"correctAnswer":"Darf ich mich vorstellen?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das ist mein ___.","options":["Kollege","Chef","Kunde","Mitarbeiter"],"correctAnswer":"Kollege"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Pleased to meet you","wordBankItems":["Angenehm",",","Sie","kennenzulernen","."],"correctAnswer":"Angenehm , Sie kennenzulernen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Beruflich'' means?","options":["professionally","privately","personally","officially"],"correctAnswer":"professionally"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000038',1,'APPROVED','PUBLISHED',
'{"objectives":["Start a conversation with strangers","Use informal du greetings","Ask simple getting-to-know-you questions"],"explanation":{"intro":"Meeting new people in informal settings uses different language from professional introductions. Learn the casual phrases for social situations.","culturalNote":"At German parties, the guest usually brings wine or a small gift. It is considered polite to bring something rather than arriving empty-handed."},"examples":[{"german":"Hey, ich bin Tom. Und du?","english":"Hey, I am Tom. And you?"},{"german":"Woher kennst du die anderen?","english":"How do you know the others?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can meet new people informally and start a conversation."}}',
'{"items":[{"word":"kennenlernen","translation":"to get to know","pronunciation":"KEN-en-ler-nen","example":"Schön, dich kennenzulernen."},{"word":"woher","translation":"from where","pronunciation":"voh-HAYR","example":"Woher kommst du?"},{"word":"die Party","translation":"party","pronunciation":"dee PAR-tee","example":"Wer hat zur Party eingeladen?"},{"word":"gemeinsam","translation":"in common/together","pronunciation":"geh-MYN-zahm","example":"Was haben wir gemeinsam?"},{"word":"übrigens","translation":"by the way","pronunciation":"ÜB-ri-gens","example":"Übrigens, ich bin Stefan."},{"word":"schön","translation":"nice/good (conversational)","pronunciation":"SHÖN","example":"Schön, dich kennenzulernen!"}]}',
'{"title":"Schön + zu + infinitive","pattern":"Schön, dich/Sie + kennenzulernen","explanation":"Schön, dich kennenzulernen = Nice to meet you (informal). Schön, Sie kennenzulernen = Nice to meet you (formal). The infinitive with zu is fixed here. Alternatively: Freut mich (Pleased to meet you) is also common.","examples":[{"sentence":"Schön, dich zu treffen!","translation":"Nice to meet you!"},{"sentence":"Freut mich, Sie kennenzulernen.","translation":"Pleased to meet you."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Kennenlernen'' means?","options":["to get to know","to say goodbye","to greet","to work with"],"correctAnswer":"to get to know"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Nice to meet you (informal).","options":["Schön, dich kennenzulernen!","Guten Tag!","Auf Wiedersehen!","Wie geht es Ihnen?"],"correctAnswer":"Schön, dich kennenzulernen!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Woher ___ du?","options":["kommst","kommt","kommen","komme"],"correctAnswer":"kommst"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: By the way I am Stefan","wordBankItems":["Übrigens",",","ich","bin","Stefan","."],"correctAnswer":"Übrigens , ich bin Stefan ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gemeinsam'' means?","options":["in common","together","friendly","similar"],"correctAnswer":"in common"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-000000000039',1,'APPROVED','PUBLISHED',
'{"objectives":["Make small talk in German","Comment on the weather","Ask about plans and weekend"],"explanation":{"intro":"Small talk is an important social lubricant. In Germany, weather and weekend plans are common topics.","culturalNote":"While Germans can seem reserved initially, small talk with neighbours, shop assistants and colleagues is quite normal. Weather (Wetter) is a universal opener."},"examples":[{"german":"Schönes Wetter heute, oder?","english":"Nice weather today, isn''t it?"},{"german":"Haben Sie schöne Pläne fürs Wochenende?","english":"Do you have nice plans for the weekend?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can make small talk about weather and weekend plans."}}',
'{"items":[{"word":"oder?","translation":"isn''t it? / right?","pronunciation":"OH-der","example":"Schön, oder?"},{"word":"stimmt","translation":"that''s right / true","pronunciation":"SHTIMT","example":"Ja, stimmt!"},{"word":"echt","translation":"really / genuinely","pronunciation":"EKHT","example":"Echt? Das ist toll!"},{"word":"der Plan","translation":"plan","pronunciation":"dayr PLAHN","example":"Hast du Pläne?"},{"word":"eigentlich","translation":"actually","pronunciation":"EY-gent-likh","example":"Eigentlich, ja."},{"word":"na ja","translation":"well / oh well","pronunciation":"nah YAH","example":"Na ja, es geht."}]}',
'{"title":"Oder? — tag questions","pattern":"statement + , oder? = tag question","explanation":"Add oder? at the end of a statement to make a tag question. Schönes Wetter, oder? = Nice weather, isn''t it? It is the simplest tag question in German — unlike English which varies (isn''t it, doesn''t he, weren''t they).","examples":[{"sentence":"Das ist toll, oder?","translation":"That is great, isn''t it?"},{"sentence":"Du kommst morgen, oder?","translation":"You are coming tomorrow, aren''t you?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Stimmt'' means?","options":["that''s right","really","actually","well"],"correctAnswer":"that''s right"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Really? That is great!","options":["Echt? Das ist toll!","Stimmt, oder?","Na ja, es geht.","Eigentlich ja."],"correctAnswer":"Echt? Das ist toll!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Schönes Wetter heute, ___?","options":["oder","nicht","ja","doch"],"correctAnswer":"oder"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Do you have plans?","wordBankItems":["Hast","du","Pläne","?"],"correctAnswer":"Hast du Pläne ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Eigentlich'' means?","options":["actually","really","right","well"],"correctAnswer":"actually"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-00000000003a',1,'APPROVED','PUBLISHED',
'{"objectives":["Give and receive compliments","React naturally","Use Das steht dir gut"],"explanation":{"intro":"Giving compliments is a key social skill. Germans tend to be direct — compliments are genuine rather than formulaic.","culturalNote":"Germans may not compliment as freely as in some cultures, but when they do it is sincere. Accepting compliments graciously rather than deflecting is appreciated."},"examples":[{"german":"Das steht dir sehr gut!","english":"That suits you very well!"},{"german":"Du hast eine tolle Stimme.","english":"You have a great voice."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can give and respond to compliments in German."}}',
'{"items":[{"word":"Das steht dir gut","translation":"That suits you","pronunciation":"dahs SHTEYT deer GOOT","example":"Das steht dir gut!"},{"word":"toll","translation":"great/fantastic","pronunciation":"TOL","example":"Das ist toll!"},{"word":"wunderschön","translation":"beautiful","pronunciation":"VOON-der-shön","example":"Das ist wunderschön."},{"word":"klasse","translation":"brilliant (colloquial)","pronunciation":"KLAS-seh","example":"Das ist klasse!"},{"word":"Danke schön","translation":"Thank you very much","pronunciation":"DAN-keh SHÖN","example":"Danke schön!"},{"word":"Du bist...","translation":"You are...","pronunciation":"doo BIST","example":"Du bist sehr talentiert."}]}',
'{"title":"Das steht dir/Ihnen gut — complimenting appearance","pattern":"Das steht dir (inf.) / Ihnen (formal) gut","explanation":"Das steht dir gut is the standard way to say something suits someone. Stehen here means to suit. Steht is 3rd person singular of stehen. Dir = dative of du (informal), Ihnen = dative of Sie (formal).","examples":[{"sentence":"Die Jacke steht dir gut.","translation":"The jacket suits you."},{"sentence":"Das steht Ihnen sehr gut.","translation":"That suits you very well. (formal)"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Klasse'' means in colloquial German?","options":["brilliant","class","lesson","grade"],"correctAnswer":"brilliant"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"That suits you very well!","options":["Das steht dir sehr gut!","Du bist toll!","Das ist wunderschön.","Danke schön!"],"correctAnswer":"Das steht dir sehr gut!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das ___ dir gut.","options":["steht","ist","hat","geht"],"correctAnswer":"steht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: You are very talented","wordBankItems":["Du","bist","sehr","talentiert","."],"correctAnswer":"Du bist sehr talentiert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Wunderschön'' means?","options":["beautiful","wonderful","great","nice"],"correctAnswer":"beautiful"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-00000000003b',1,'APPROVED','PUBLISHED',
'{"objectives":["Apologise in German","Accept an apology","Use Entschuldigung and Es tut mir leid"],"explanation":{"intro":"Apologising well is an important social skill. German has distinct expressions for minor mishaps and serious apologies.","culturalNote":"Entschuldigung is used for minor things like bumping into someone or being late. Es tut mir leid (I am sorry) is more sincere and for serious apologies."},"examples":[{"german":"Entschuldigung, das war mein Fehler.","english":"I am sorry, that was my mistake."},{"german":"Es tut mir sehr leid.","english":"I am very sorry."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can apologise and accept apologies in German."}}',
'{"items":[{"word":"Entschuldigung","translation":"Sorry / Excuse me","pronunciation":"ent-SHOOL-dee-goong","example":"Entschuldigung bitte!"},{"word":"Es tut mir leid","translation":"I am sorry","pronunciation":"es TOOT meer LYTE","example":"Es tut mir leid."},{"word":"der Fehler","translation":"mistake","pronunciation":"dayr FAY-ler","example":"Das war mein Fehler."},{"word":"kein Problem","translation":"no problem","pronunciation":"kyne proh-BLAYM","example":"Kein Problem!"},{"word":"macht nichts","translation":"never mind / it does not matter","pronunciation":"MAKHT NIKHTS","example":"Macht nichts!"},{"word":"absichtlich","translation":"on purpose","pronunciation":"AP-zikht-likh","example":"Das war nicht absichtlich."}]}',
'{"title":"Es tut mir leid — expressing regret","pattern":"Es tut mir leid + (dass + sentence) / + noun","explanation":"Es tut mir leid expresses genuine regret. It literally means it does pain me. Leid is an adjective/noun here. For stronger apologies: Es tut mir sehr leid. You can add a reason: Es tut mir leid, dass ich zu spät bin.","examples":[{"sentence":"Es tut mir leid, dass ich das vergessen habe.","translation":"I am sorry that I forgot that."},{"sentence":"Es tut mir wirklich leid.","translation":"I am truly sorry."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Macht nichts'' means?","options":["never mind","no problem","sorry","excuse me"],"correctAnswer":"never mind"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"That was my mistake.","options":["Das war mein Fehler.","Es tut mir leid.","Kein Problem!","Das war nicht absichtlich."],"correctAnswer":"Das war mein Fehler."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Es tut mir sehr ___.","options":["leid","lied","lieb","leib"],"correctAnswer":"leid"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: No problem!","wordBankItems":["Kein","Problem","!"],"correctAnswer":"Kein Problem !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Absichtlich'' means?","options":["on purpose","accidentally","probably","possibly"],"correctAnswer":"on purpose"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES
('aa000000-0000-0000-0000-00000000003c',1,'APPROVED','PUBLISHED',
'{"objectives":["Thank people in various ways","Respond to thanks","Use Danke in different registers"],"explanation":{"intro":"Germans have various ways to express gratitude depending on the level of formality and depth of thanks.","culturalNote":"Vielen Dank (many thanks) is slightly more formal than Danke schön. In business settings, Herzlichen Dank (heartfelt thanks) is common."},"examples":[{"german":"Vielen Dank für Ihre Hilfe.","english":"Many thanks for your help."},{"german":"Keine Ursache!","english":"You are welcome! (No reason to thank me)"}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can express and respond to gratitude appropriately."}}',
'{"items":[{"word":"Danke schön","translation":"Thank you very much","pronunciation":"DAN-keh SHÖN","example":"Danke schön!"},{"word":"Vielen Dank","translation":"Many thanks","pronunciation":"FEE-len DANK","example":"Vielen Dank!"},{"word":"Herzlichen Dank","translation":"Heartfelt thanks","pronunciation":"HERTS-likhen DANK","example":"Herzlichen Dank für alles."},{"word":"Bitte sehr","translation":"You are welcome (here you go)","pronunciation":"BIT-teh ZAYR","example":"Bitte sehr!"},{"word":"Keine Ursache","translation":"No reason / You are welcome","pronunciation":"KY-neh OOR-zah-kheh","example":"Keine Ursache!"},{"word":"Gern geschehen","translation":"My pleasure","pronunciation":"GERN geh-SHAY-en","example":"Gern geschehen!"}]}',
'{"title":"Für + accusative — thanking for something","pattern":"Danke/Vielen Dank für + accusative noun","explanation":"To thank someone for something, use für + accusative. Danke für die Hilfe = Thanks for the help. Vielen Dank für Ihre Zeit = Thank you very much for your time. Für always takes accusative.","examples":[{"sentence":"Danke für das Geschenk.","translation":"Thanks for the present."},{"sentence":"Herzlichen Dank für Ihre Unterstützung.","translation":"Heartfelt thanks for your support."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gern geschehen'' means?","options":["my pleasure","no problem","thank you","sorry"],"correctAnswer":"my pleasure"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Many thanks for your help.","options":["Vielen Dank für Ihre Hilfe.","Bitte sehr!","Gern geschehen!","Keine Ursache!"],"correctAnswer":"Vielen Dank für Ihre Hilfe."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Danke ___ das Geschenk.","options":["für","von","mit","zu"],"correctAnswer":"für"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: You are welcome!","wordBankItems":["Keine","Ursache","!"],"correctAnswer":"Keine Ursache !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bitte sehr'' means?","options":["you are welcome / here you go","please","yes please","not at all"],"correctAnswer":"you are welcome / here you go"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

